package io.knowledgebrain.planning;
import java.util.*;import java.time.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.flywaydb.core.Flyway;import org.springframework.jdbc.core.JdbcTemplate;import org.apache.kafka.clients.consumer.*;import io.knowledgebrain.contracts.planning.goal.v1.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_KAFKA_BOOTSTRAP",matches=".+")
class GoalKafkaIntegrationTest {
 @Test void committedCreateEditReopenAndRetirementReachKafkaWithExactStableEnvelopeBytes()throws Exception{var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var store=new GoalStore(ds,Clock.systemUTC());var ids=new UuidV7(Clock.systemUTC());var space=ids.next();var actor=ids.next();String trace="e".repeat(32),key=UUID.randomUUID().toString().replace("-","");var initial=new GoalStore.Input("Kafka goal","Original","NOT_STARTED","2028-02-29");var goal=store.create(space,actor,key,initial,trace).goal();store.create(space,actor,key,initial,trace);store.change(space,goal.goalId(),actor,1,new GoalStore.Input("Completed","Edited","COMPLETED",null),false,trace);store.change(space,goal.goalId(),actor,2,new GoalStore.Input("Reopened","Edited","IN_PROGRESS","2028-03-01"),false,trace);store.change(space,goal.goalId(),actor,3,null,true,trace);var expected=new HashMap<String,byte[]>();new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregateid=?",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),goal.goalId()).forEach(e->expected.put(e.getKey(),e.getValue()));assertEquals(4,expected.size());var p=new Properties();p.put("bootstrap.servers",System.getenv("BRAIN_TEST_PLANNING_KAFKA_BOOTSTRAP"));p.put("group.id","planning-validation-"+ids.next());p.put("enable.auto.commit","false");p.put("auto.offset.reset","earliest");p.put("key.deserializer","org.apache.kafka.common.serialization.StringDeserializer");p.put("value.deserializer","org.apache.kafka.common.serialization.ByteArrayDeserializer");p.put("security.protocol","SSL");p.put("ssl.endpoint.identification.algorithm","HTTPS");p.put("ssl.truststore.type","PEM");p.put("ssl.truststore.certificates",Files.readString(Path.of("/planning-kafka-test/ca.crt")));p.put("ssl.keystore.type","PEM");p.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/planning-kafka-test/user.crt")));p.put("ssl.keystore.key",Files.readString(Path.of("/planning-kafka-test/user.key")));try(var c=new KafkaConsumer<String,byte[]>(p)){c.subscribe(List.of("planning.goal.v1"));var found=new HashSet<String>();var versions=new ArrayList<Long>();long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<4&&System.nanoTime()<deadline)for(var row:c.poll(Duration.ofSeconds(1))){if(!goal.goalId().toString().equals(row.key()))continue;var e=GoalEventEnvelopeV1.parseFrom(row.value());var v=GoalChangedPayloadV1.parseFrom(e.getPayload());assertArrayEquals(expected.get(e.getEventId()),row.value());assertEquals("planning-service",e.getProducer());assertEquals("Goal",e.getAggregateType());assertEquals(space.toString(),e.getSpaceId());assertEquals(actor.toString(),e.getActorId());assertEquals(trace,e.getTraceId());assertEquals(1,e.getEventVersion());assertEquals(7,UUID.fromString(e.getEventId()).version());assertEquals(7,UUID.fromString(v.getRevisionId()).version());assertEquals("PRIVATE",v.getVisibility());assertEquals(v.getVersion()==4?"RETIRED":"ACTIVE",v.getState());assertEquals(v.getVersion()==1?"2028-02-29":v.getVersion()==2?"":"2028-03-01",v.getTargetDate());for(var pair:Map.of("id",e.getEventId(),"trace_id",trace,"schema_group","planning","schema_artifact","goal-events","schema_version","1").entrySet()){assertNotNull(row.headers().lastHeader(pair.getKey()));assertEquals(pair.getValue(),new String(row.headers().lastHeader(pair.getKey()).value(),StandardCharsets.UTF_8));}if(found.add(e.getEventId()))versions.add(v.getVersion());}assertEquals(expected.keySet(),found);assertEquals(List.of(1L,2L,3L,4L),versions);}}
}
